SELECT e.t AS tabla, e.f AS clave_ajena_que_falta
  FROM JSON_TABLE(@esperadas, '$[*]'
         COLUMNS (t VARCHAR(64) PATH '$.t', f VARCHAR(64) PATH '$.f')) AS e
  LEFT JOIN information_schema.table_constraints c
         ON c.constraint_schema = 'gestek_datos'
        AND c.constraint_type   = 'FOREIGN KEY'
        AND c.table_name        = e.t
        AND c.constraint_name   = e.f
 WHERE c.constraint_name IS NULL;
